mapper.select:
SELECT COALESCE(SUM(duration) / 3600.0, 0)
FROM student_checkin
WHERE student_id = #{studentId}

SELECT COALESCE(AVG(score), 0)
FROM homework_scores
WHERE student_id = #{studentId}

SELECT DAY(checkin_date)
FROM student_checkin
WHERE student_id = #{studentId} AND DATE_FORMAT(checkin_date, '%Y-%m') = #{yearMonth}

SELECT COUNT(DISTINCT checkin_date)
FROM student_checkin
WHERE student_id = #{studentId} AND checkin_date BETWEEN #{startDate} AND #{endDate}

SELECT COUNT(*)
FROM (
    SELECT sc.student_id, COUNT(DISTINCT sc.checkin_date) as day_count
    FROM student_checkin sc
    JOIN student_profile sp ON sc.student_id = sp.id
    WHERE sp.class_id = CONVERT(#{classId}, CHAR) COLLATE utf8mb4_unicode_ci
      AND sc.checkin_date BETWEEN #{startDate} AND #{endDate}
    GROUP BY sc.student_id
    HAVING day_count >= #{threshold}
) qualified
